INSERT INTO "queue" VALUES(1,'https://godliteratury.ru/articles/2026/09/27/rodina-ty-odna-bessmertna-kak-mat-effendi-kapiev','Год литературы','«Родина, ты одна бессмертна, как мать». Эффенди Капиев','Эффенди Капиев родился в лакском селении Кумух в семье замечательного мастера-ювелира. В детстве жил подл Ставрополем, после революции — в Буйнакске. Там окончил педагогический техникум, там и учительствовал. К 1934 году Капиев стал активным участником литературной жизни Дагестана. Он — вместе с другими кавказскими литераторами — даже встретился с Максимом Горьким , читал ему свои стихи. Наибольшую известность Капиев получил как переводчик Сулеймана Стальского , стихи которого в то время громко звучали по всей стране.','https://glstatic.rg.ru/uploads/images/2026/09/26/image_780.png','2026-09-27T07:00:00+00:00','posted','2026-09-27T14:37:39.696472+00:00','2026-09-27T14:55:40.004794+00:00',NULL,0);
INSERT INTO "queue" VALUES(2,'https://gorky.media/reviews/tsirkumlatorii-stalin-knigi-nedeli','Горький','Циркумлаторий Сталин: книги недели','Немецкие философы Адорно, Хоркхаймер и Блох практически одновременно уехали из Германии и практически одновременно вернулись. Все трое, пока находились в США, работали над исследованиями европейской цивилизации, однако выводы из своей работы сделали противоположные. Если Адорно с Хоркхаймером поставили ей максимально неутешительный диагноз в «Диалектике Просвещения», то Блох, напротив, усиленно нащупывал светлые перспективы нашего коллективного будущего. Работа «Свобода и порядок», опубликованная отдельной книгой в 1947 году, впоследствии вошла в трехтомный труд «Принцип надежды», блоховский…','https://gorky.media/storage/seo/4db9c4f94bf72e242572ed7c4e931987_large.jpg',NULL,'posted','2026-09-27T14:37:39.704206+00:00','2026-09-27T15:40:55.771685+00:00',NULL,0);
INSERT INTO "queue" VALUES(3,'https://textura.club/sto-let/','Textura','Сто лет спустя. Михаил Гундарин о книге Владимира Семенова «Ирод: кровь и храм»','Книга Владимира Семенова написана вполне себе современно, по хорошо знакомой нынешнему читателю сюжетной схеме. «Роман в романе», где современная история — Арсений Мамаев, послушник и историк, пишет книгу об Ироде Великом, одновременно участвуя в строительстве нового храма в Москве — переплетается с древним повествованием о царе Иудеи, его кровавом правлении и воссоздании Второго Храма. Однако важнее не фабула, а эстетическая и метафизическая традиция, к которой «Ирод» принадлежит. Читатель понимает буквально с первых строк — автор ставит своей перспективой продолжение и переосмысление…','','2026-09-27T13:49:39+00:00','posted','2026-09-27T14:37:39.711801+00:00','2026-09-27T16:26:03.530778+00:00',NULL,0);
INSERT INTO "queue" VALUES(4,'https://lgz.ru/news/bulgakov-s-muzykoj-2/','Литературная газета','Булгаков с музыкой','29 сентября в 20:00 в Московском театре Всеволода Шиловского состоится показ документально-музыкальной постановки «Булгаков с музыкой», который даст старт новому сезону проекта «Автор решил, что пора начинать». В год 135-летия со дня рождения Михаила Афанасьевича Булгакова проект родился и начал расширять свою географию. Следующий показ байопик-постановки пройдёт 7 ноября в 19:00 в Творческой мастерской «Цвет и Звук».','https://lgz.ru/upload/opt/kvadrat-bulgakov-bez-dat.jpeg','2026-09-27T14:25:39+04:00','posted','2026-09-27T14:37:39.719975+00:00','2026-09-27T17:11:19.909154+00:00',NULL,0);
INSERT INTO "queue" VALUES(5,'https://knife.media/drugimi-slovami-kniga-vs-film/','Нож','Другими словами: почему экранизация книги не обязана быть похожей на оригинал','Спор «книга лучше фильма» (комикс, графический роман, газета — вставьте нужное слово) не утихнет, наверное, никогда. Достаточно вспомнить, как поклонники киноадаптаций и фанаты комиксов DC раз за разом сходятся в яростных баталиях из-за трактовки образа Бэтмена. А уж про совсем свежий кейс с «Одиссеей» мы и вовсе промолчим, ибо ну сколько можно. Однако, прежде чем занимать места в одном из лагерей, стоит признать: сама постановка вопроса хромает. Экранизация не обязана быть точной иллюстрацией литературного произведения — и дело здесь не в снисходительности к режиссёрам, а в том, что книга и…','https://knife.media/wp-content/uploads/social-image/273455-6ab69ce7c9807.jpg','2026-09-27T07:00:14+00:00','posted','2026-09-27T14:37:39.727407+00:00','2026-09-27T18:20:07.138603+00:00',NULL,0);
INSERT INTO "queue" VALUES(6,'https://godliteratury.ru/articles/2026/09/27/talalaj-mihail-moskva-italianskaia','Год литературы','Талалай Михаил «Москва итальянская»','«Москва итальянская» — это удивительная книга историка Михаила Талалая (вышедшая в издательстве «Слово/Slovo»), которая читается как захватывающий роман о притяжении между двумя культурами. Автор показывает, как на протяжении веков итальянцы бережно и с душой создавали облик нашей столицы — от кирпичиков Кремля до кулинарных традиций и уличной моды. Это не скучный академический труд, а живое переплетение архивных находок, личных писем и трогательных человеческих судеб, которое зацепит каждого, кто влюблен в Москву и ее скрытые смыслы.','https://glstatic.rg.ru/uploads/images/2026/09/22/image_423.png','2026-09-27T05:15:00+00:00','posted','2026-09-27T14:37:39.738999+00:00','2026-09-27T19:32:10.795165+00:00',NULL,0);
INSERT INTO "queue" VALUES(7,'https://gorky.media/fragments/paroxodnye-bezobraziya','Горький','Пароходные безобразия','Псков, Великий Новгород, Владимир, Москва, Тверь, Смоленск, Нижний Новгород, Оренбург, Пермь, Казань, Тюмень, Тобольск, Красноярск, Иркутск, Якутск, Благовещенск, Хабаровск, Охотск, Санкт-Петербург, Николаев-на-Амуре, будучи своеобразными вехами отечественной истории, стоят на реках.','https://gorky.media/storage/seo/1e1dc7a76f73b674c725539139cb19b1_large.jpg',NULL,'posted','2026-09-27T14:37:39.746833+00:00','2026-09-28T05:01:09.996977+00:00',9,1);
INSERT INTO "queue" VALUES(8,'https://textura.club/sled/','Textura','След. Стихи Руслана Акаева','посреди дороги — женщина тянет ребенка он упирается: тут нельзя она стискивает руку дергает торможу ее взгляд царапает лобовое пропускаю
INSERT INTO "queue" VALUES(9,'https://lgz.ru/news/bolee-90-sobytij/','Литературная газета','Более 90 событий','На официальном сайте Нижегородской книжной ярмарки опубликована программа для посетителей. Со 2 по 4 октября 2026 года в пассаже Главного ярмарочного дома запланировано более 90 событий: творческие встречи с писателями, презентации книжных новинок, лекции, спектакли, дискуссии и другие мероприятия для взрослых и детей. Вход на ярмарку и все мероприятия программы свободный.','https://lgz.ru/upload/opt/sgt10gezamhifbvesy0tkpfl1trmb77l.jpeg','2026-09-27T10:01:06+04:00','posted','2026-09-27T14:37:39.760658+00:00','2026-09-28T06:32:09.780093+00:00',11,1);
INSERT INTO "queue" VALUES(10,'https://godliteratury.ru/articles/2026/09/26/300-let-puteshestviiu-gullivera-dzhonatana-svifta-test','Год литературы','300 лет «Путешествию Гулливера» Джонатана Свифта. Тест','В 2026 году исполняется 300 лет со дня первой публикации знаменитого романа Джонатана Свифта «Путешествия Гулливера», вышедшего в свет в 1726 году. Дата выхода: Роман был впервые опубликован в октябре 1726 года в Лондоне. Полное название: «Путешествия в некоторые отдалённые страны мира в четырёх частях: сочинение Лемюэля Гулливера, сначала хирурга, а затем капитана нескольких кораблей». Книга состоит из четырёх частей, описывающих фантастические путешествия главного героя в страну крошечных лилипутов, к гигантским великанам, на летающий остров Лапуту и в землю разумных лошадей-гуигннмов. Под…','https://glstatic.rg.ru/uploads/images/2026/09/11/image_a26.jpg','2026-09-26T08:00:00+00:00','posted','2026-09-27T14:37:39.768015+00:00','2026-09-28T07:15:44.925832+00:00',12,1);
INSERT INTO "queue" VALUES(11,'https://gorky.media/reviews/more-vysoxlo-pamyat-ostalas','Горький','Море высохло, память осталась','У романа Дании Жанси «DRUZHBA» есть качество, которое сегодня встречается не так уж часто: ему действительно есть что защищать от забвения. Казань начала XX века, татарский язык и книжная культура, история каракалпаков, Арал, семейная память, несколько любовных историй, протянувшихся через поколения, — автор собирает все это в одну конструкцию, в которой прошлое постоянно просачивается в настоящее.','https://gorky.media/storage/seo/cd3105683430cf99ec5f01eec776cccd_large.jpg',NULL,'ready','2026-09-27T14:37:39.776738+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(12,'https://lgz.ru/news/czvetaevskaya-osen/','Литературная газета','Цветаевская осень','27 сентября и 22 ноября в 19:00 на Новой сцене Театра «МОСТ» состоятся особенные, почти сакральные показы спектакля «Марина Цветаева. Повесть о Сонечке» — осенью (26 сентября (8 октября по новому стилю) 1892) родилась знаковая фигура отечественной культуры первой половины XX века Марина Цветаева. Эти показы дадут опыт личной встречи с великим поэтом. Спектакль представлен рамках проекта «КультПросвет. Эпоха в лицах».','https://lgz.ru/upload/opt/i-13.jpeg','2026-09-27T00:33:10+04:00','ready','2026-09-27T14:37:39.783792+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(13,'https://godliteratury.ru/articles/2026/09/26/chto-putin-predlozhil-drugim-stranam-na-forume-obedinennyh-kultur-v-peterburge','Год литературы','Что Путин предложил другим странам на Форуме объединенных культур в Петербурге','Россия выстраивает свою культуру не как привилегию, а как право и возможность для каждого человека. Об этом президент РФ Владимир Путин заявил, выступая сегодня на XII Санкт-Петербургском международном форуме объединенных культур. Президент также говорил о том, как сохранять диалог между странами, даже когда политические и экономические связи ограничены.','https://glstatic.rg.ru/uploads/images/2026/09/26/5y6a1513jpg_e32_7cf.jpg','2026-09-26T07:43:00+00:00','ready','2026-09-27T14:37:39.791373+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(14,'https://gorky.media/context/romanticheskii-egoist','Горький','«Романтический эгоист»','Как громогласно заявил сам прозаик в рассказе «Пловцы» 1929 года, «Америка… — это и могилы в Шайло, и усталые, напряженные и нервные лица ее великих сынов, и деревенские мальчишки, умиравшие в Аргонском лесу во имя того, что забыли скорее, чем их тела забросали землею. Она — вечная готовность сердца к жертве». В этой формуле — весь Фицджеральд, с его фанатичной одержимостью темой американской мечты и американского видения мира: это молодая, праздная нация вечеринок, излишества и алкоголя, но это также вынужденное забытие, пришедшее в страну слишком рано.','https://cdn.gorky.media/storage/files/7f8166387e2a1ecaf6378fb0783a3428_large.jpg',NULL,'ready','2026-09-27T14:37:39.798288+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(15,'https://lgz.ru/article/geroi-almanaha-kinoreportera-vstretilis-s-chitatelyami/','Литературная газета','Герои альманаха «КиноРепортера» встретились с читателями','В московском книжном магазине РЕСПУБЛИКА состоялась встреча читателей журнала «КиноРепортер» с героями его коллекционного альманаха «Времена года». Интерес к событию оказался настолько высоким, что регистрация завершилась почти сразу после анонса – поступило более 130 заявок. На одной площадке встретились актеры и читатели, представители киноиндустрии и поклонники российского кино – чтобы поговорить о съемках, профессии, фотографии и тех историях, которые обычно остаются за пределами кадра.','https://lgz.ru/upload/opt/valentina-lyapina-denis-vasilev-marusya-klimova-oleg-savostyuk.-lyubov-shemetova.jpeg','2026-09-26T21:20:06+04:00','ready','2026-09-27T14:37:39.805231+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(16,'https://godliteratury.ru/articles/2026/09/26/mihail-piotrovskij-o-forume-obedinennyh-kultur-iskusstvennom-intellekte-i-blokade-ermitazha','Год литературы','Михаил Пиотровский — о форуме объединенных культур, искусственном интеллекте и блокаде Эрмитажа','24 сентября открылся XII Санкт-Петербургский форум объединенных культур. Эрмитаж по традиции — его главная рабочая площадка. Официальные делегации более, чем из 50 стран, две с половиной тысячи участников, десятки актуальных дискуссий с международными экспертами и лицами и лидерами культурной индустрии. Наш собеседник, директор Эрмитажа, академик РАН и РАХ Михаил Борисович Пиотровский — куратор музейной площадки и один из ключевых спикеров форума по проблемам диалога культур и сохранения культурного многообразия мира, рассказал "РГ" о главных идеях, ожиданиях и настроениях форума.','https://glstatic.rg.ru/uploads/images/2026/09/26/image_2b9.png','2026-09-26T07:13:00+00:00','ready','2026-09-27T14:37:39.811914+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(17,'https://gorky.media/fragments/eto-chistoe-zoloto','Горький','«Это чистое золото»','На первый взгляд, все до смешного просто: берешь бойко продающуюся книгу, перепечатываешь, оформляешь, рекламируешь, отправляешь — и можно подсчитывать прибыль. Причем, как правило, даже не нарушая закона, поскольку международной системы копирайта еще не существовало и голландские или швейцарские издатели могли безнаказанно воспроизводить выходившие во Франции сочинения. Конечно, французские издатели протестовали против действий «пиратов», «корсаров», «бандитов» — так они в переписке именовали своих заграничных конкурентов. На самом же деле книжные пираты в основном были респектабельными…','https://gorky.media/storage/seo/1f83da2fee2d5abf2a6f851142446c31_large.jpg',NULL,'ready','2026-09-27T14:37:39.818506+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(18,'https://gorky.media/reviews/rynok-bez-rynka','Горький','Рынок без рынка','Сегодня у нас не вызывает сомнений, что любой товар или услуга могут быть измерены в ценах, которые формируются объемом спроса и предложения на рынке, где действуют свободные агенты-индивидуалисты. Эта логика настолько вездесуща, что ее распространяют и на внеэкономические явления: качество образования, содержание произведения искусства или наполнение дружеской связи, а иногда само измерение может дойти абсурда. Современные представления о рыночном устройстве общества укоренены в традиции неоклассической экономической теории, для которой свобода личности и выбора, преследование частного…','https://gorky.media/storage/seo/0b7f94705a450e0a02a017f48cc603e5_large.jpg',NULL,'ready','2026-09-27T14:37:39.829005+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(19,'https://gorky.media/context/mesto-teologii-v-duxovnyx-uchrezhdeniyax-no-ne-v-svetskix-vuzax','Горький','«Место теологии — в духовных учреждениях, но не в светских вузах»','— Ваша книга выросла из кандидатской диссертации « Организации свободомыслящих в Германии конца ХХ — начала ХХI веков ». И для нее, и для вашей книги важен термин «свободомыслие». Расскажите, пожалуйста, о нем.','https://gorky.media/storage/seo/ae20211f1121afcdbb86d674822be035_large.jpg',NULL,'ready','2026-09-27T14:37:39.838764+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(20,'https://gorky.media/reviews/mezhdu-berlinom-i-avtofikshnom','Горький','Между Берлином и автофикшном','В издательстве «Individuum» вышел дебютный текст Даши Охоцимской «На этой планете взрослых нет»: критика назвала его «мастерским дебютом» и «искренним» текстом. Современная русскоязычная эмигрантская литература часто обращается к автофикшну: так, Лариса Муравьева в книге «Написано в Западном Берлине» (2025) через традиционные для жанра приемы смотрит на возможности художественного мира глазами исследовательницы, а поэт Сорин Брут в «Романе неотправленных писем» (2026) изобретает новый язык утраты дома: их автогерои пересобирают себя внутри катастрофы. Охоцимская тоже покинула страну, живет и…','https://cdn.gorky.media/storage/files/02185544a39653e4f310f014be563c1b_large.jpg',NULL,'ready','2026-09-27T14:37:39.849308+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(21,'https://gorky.media/fragments/domogatelstvo-zapaxom','Горький','Домогательство запахом','Первые исследования запахов человеческого тела и тех причин, по которым они возникают, побуждали некоторых врачей выдвигать самые разные гипотезы. Например, французский хирург Огюстен Жакоб Ландре-Бове, живший в начале XIX века, уверял, что люди, испытывающие сильную тоску, теряют здоровый запах тела; холерики и люди, испытывающие страх, приобретают резкий неприятный запах от подмышек, а от тех, кто в ярости, исходит невыносимый смрад.','https://gorky.media/storage/seo/90238d9e5c8d32c22b0b42bbb9ee09b0_large.jpg',NULL,'ready','2026-09-27T14:37:39.860379+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(22,'https://gorky.media/fragments/skazhi-mne-chetyre-glavnyx-slova','Горький','Скажи мне четыре главных слова','Книга, которую держит в руках читатель, вероятно, одно из наиболее известных произведений мировой средневековой литературы. Для того чтобы понять место «Саги о Волсунгах» на литературном поле, надо вкратце обрисовать своего рода карту и систему координат, в которой она существует. Среди общеиндоевропейского мифо-эпического наследия отчетливо выделяется германо-скандинавский сегмент, исторически формировавшийся в течение многих веков, отлитый в поэтические и прозаические тексты в основном в эпоху викингов и записанный в Исландии в период XII–XIV столетий. Он очень обширен: скандинавы оставили…','https://gorky.media/storage/seo/363f61dd22fefa97d434454ee87925e6_large.jpg',NULL,'ready','2026-09-27T14:37:39.870341+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(23,'https://gorky.media/context/golding-ukazuyushchii','Горький','Голдинг указующий','Некруглый юбилей Уильяма Голдинга — повод не только вспомнить склонного, по выражению литературоведа Джона Кэри, «к депрессии алкоголика» и его самую известную книгу, но и проследить влияние «Повелителя мух» на отечественную литературу последних лет. В оптике, заданной романом, выходят книги, авторы которых пытаются описать и осмыслить современные проблемы и даже наметить пути их решения.','https://gorky.media/storage/seo/0b8cffbfd24e4655615cca596093cbb3_large.jpg',NULL,'ready','2026-09-27T14:37:39.880388+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(24,'https://gorky.media/reviews/poka-ne-nastupilo-budushchee','Горький','Пока не наступило будущее','«Что вы можете рассказать о немецкой колонии в Санари?» — так в 1939 году сотрудники ФБР начали допрос немецкого писателя и философа Людвига Маркузе, бежавшего в США от нацизма. Маркузе наверняка опешил от такого вопроса, ведь речь шла о событиях шестилетней давности, а именно — лета 1933 года, когда в приморском городке Санари-сюр-Мер на юге Франции стихийно образовалось целое сообщество немецких изгнанников. Среди тех, кто решил провести первое лето эмиграции в живописном местечке на берегу Средиземного моря, был Бертольт Брехт со своей сотрудницей и любовницей Маргарет Штеффин, Лион и…','https://cdn.gorky.media/storage/files/09e8eda0ceed4293498e815afd5eec5b_large.jpg',NULL,'ready','2026-09-27T14:37:39.890419+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(25,'https://gorky.media/fragments/arabeski-groznyx-sil-prirody','Горький','Арабески грозных сил природы','При обилии учебников и печатных курсов, связанных программами, у нас еще очень мало общедоступных книг для чтения по географии, в особенности по общегеографическим вопросам.','https://gorky.media/storage/seo/0cffce35f5d1f42308ee696f76f90d95_large.jpg',NULL,'ready','2026-09-27T14:37:39.901427+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(26,'https://gorky.media/reviews/v-italii-nado-zhit-dolgo','Горький','В Италии надо жить долго','Федор Васильевич Чижов известен в истории России XIX века как финансист, промышленник, один из пионеров строительства железных дорог, меценат, один из деятелей кружка московских славянофилов. Вышедшая в Санкт-Петербурге книга представляет читателю Чижова как путешественника по Италии, влюбленного в ее культуру.','https://gorky.media/storage/seo/1494fafd4413c77563213ddfc15ffa5f_large.jpg',NULL,'ready','2026-09-27T14:37:39.912323+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(27,'https://gorky.media/context/realist-fantastiki','Горький','Реалист фантастики','Первый свой роман, политический памфлет Desert Daisy , Герберт Уэллс сочинил в 13 лет. Долгое время эта книга оставалась единственным его литературным опытом. До 18 лет занятия будущего классика научной фантастики не имели отношения ни к литературе, ни к науке: окончив частную школу, Герберт служил помощником продавца тканями и аптекаря, ассистентом школьного учителя. В 1884–1887 годах он получил естественно-научное образование в Нормальной школе наук (в российской системе это примерно соответствует педагогическому колледжу), где биологию преподавал «бульдог Дарвина» Томас Хаксли (Гексли)…','https://gorky.media/storage/seo/b4763d64ef89cf7b0da367121e04c2b4_large.jpg',NULL,'ready','2026-09-27T14:37:39.919686+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(28,'https://gorky.media/reviews/xorosho-temperirovannyi-chrokodil-knigi-nedeli','Горький','Хорошо темперированный чрокодил: книги недели','Частная художественная школа Елизаветы Званцевой просуществовала в Петербурге с 1906 по 1917 год, в ней преподавали Мстислав Добужинский, Лев Бакст и Кузьма Петров-Водкин, а среди учеников были Марк Шагал, Михаил Матюшин, Надежда Лермонтова, Юлия Оболенская и Сергей Калмыков. Школа занимала этаж в знаменитом доме на Таврической, над «башней» Вячеслава Иванова, и довольно быстро стала одним из мест, где новая русская живопись училась лучше понимать саму себя.','https://gorky.media/storage/seo/d0eaa1ed641fd5fd6a2a7b39d5ced948_large.jpg',NULL,'ready','2026-09-27T14:37:39.928101+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(29,'https://gorky.media/context/tsirkach-stixa','Горький','Циркач стиха','Семен Кирсанов (Кортчик) родился 5 (18) сентября 1906 года в Одессе, которая «в те времена была очень литературным городом. Писателей насчитывалось штук 500» — как писал он в своей шуточной автобиографии для сборника «15 лет русского футуризма. 1912–1927 гг.»:
INSERT INTO "queue" VALUES(30,'https://gorky.media/fragments/strast-k-malenkim-lionskim-sobachkam','Горький','Страсть к маленьким лионским собачкам','После приобретения питомца новому владельцу предстояло кормить животное и заботиться о нем. Франческо Петрарка (1304–1374) был образцом ученого мужа, держащего питомцев, и по его письмам можно составить общее представление о природе владения животными. У него было несколько собак. Первое упоминание о собаке появляется в письме 1338 г. к Джакомо Колонне. В то время Петрарка жил в Воклюзе, и в письме он излагает причины, побуждающие его жить в столь уединенном месте, и говорит, что у него нет спутников, кроме верной собаки и слуг.','https://gorky.media/storage/seo/3740e8702a50d4571e14a02ad1a0a3b3_large.jpg',NULL,'ready','2026-09-27T14:37:39.941678+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(31,'https://lgz.ru/article/idealnaya-hrustyashhaya-kapusta-s-pervogo-raza-proverennyj-reczept-ot-vkusvill-kotoryj-rabotaet-bezotkazno/','Литературная газета','Идеальная хрустящая капуста с первого раза: проверенный рецепт от ВкусВилл, который работает безотказно','Как рассказывает нам автор канала «Книги. Издательство АСТ», этот рецепт квашеной капусты от ВкусВилл поможет сделать всё идеально с первого раза. Главное — соблюдать пропорции и следить за процессом, вовремя помогая ему.
INSERT INTO "queue" VALUES(32,'https://godliteratury.ru/articles/2026/09/28/genij-ili-zlodej-pavel-basinskij-o-dramaturge-aleksandre-suhovo-kobyline','Год литературы','Гений или злодей? Павел Басинский о драматурге Александре Сухово-Кобылине','Так совпало, что на днях в Доме русского зарубежья мы вручали Литературную премию Александра Солженицына прозаику и эссеисту Владиславу Отрошенко, а именно он является автором лучшей биографии Сухово-Кобылина, недавно вышедшей в издательстве АСТ (Редакция Елены Шубиной) и некоторое время продержавшейся в списках бестселлеров. И едва ли причиной тому был могучий интерес читающей публики к личности Александра Васильевича, чье имя не слишком-то на слуху. Скорее, причиной было качество написанной книги, художественно соединяющей в себе биографию и увлекательное уголовное расследование.','https://glstatic.rg.ru/uploads/images/2026/09/27/image_6ad.png','2026-09-28T01:40:00+00:00','ready','2026-09-28T02:31:49.756862+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(33,'https://godliteratury.ru/articles/2026/09/28/novye-trejlery-russkaia-klassika-goticheskij-miuzikl-i-antiutopiia','Год литературы','Новые трейлеры: русская классика, готический мюзикл и антиутопия','Нас ждет очень интересное кинематографическое завершение года и интересный 2027: осень уже заполнена «Сумерками» и ожиданием новых экранизаций Джейн Остин , запланированы премьеры новых «Отверженных» и киноверсии «Рождественской истории» , все замерли в ожидании последней «Дюны» и очередного спиноффа «Голодных игр» , про зимнюю премьеру «Гарри Поттера» мы уже показывали, но и 2027 год обещает быть интересным.','https://glstatic.rg.ru/uploads/images/2026/09/27/treylery-zahodnye_ee6.jpg','2026-09-28T04:15:00+00:00','ready','2026-09-28T04:32:10.813200+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(34,'https://godliteratury.ru/articles/2026/09/28/naciia-chitatelej-kak-singapur-budet-platit-grazhdanam-za-chtenie-knig','Год литературы','«Нация читателей». Как Сингапур будет платить гражданам за чтение книг?','В сентябре 2026 года Национальный библиотечный совет Сингапура запустил ReadSG , пятилетнюю национальную кампанию, которая должна превратить чтение в ежедневную привычку. Ее амбассадором выступил президент страны Тарман Шанмугаратнам , а запуск приурочили к первому в истории Сингапура Национальному месяцу чтения.','https://glstatic.rg.ru/uploads/images/2026/09/27/diting_result_d4a476d4bab411f1a185b63a0c537e8b_1_8fa.jpeg','2026-09-28T04:32:00+00:00','ready','2026-09-28T05:31:54.946645+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(35,'https://lgz.ru/article/zhelaya-schastya-lyudyam-na-zemle/','Литературная газета','Желая счастья людям на Земле','Книга Геннадия Иванова «Яблоки из аула Цада» посвящена памяти его друга, народного поэта Дагестана Магомеда Ахмедова. В стихах, вошедших в сборник, нашли отражение впечатления от поездок на Кавказ, от соприкосновения с историей и культурой этого самобытного региона. Но в первую очередь эта книга – о дружбе и братстве людей, о родстве разных народов, живущих в нашей большой и прекрасной стране, о ценности и необходимости общения, которое обогащает и укрепляет. Показательно в этом отношении стихотворение, которое начинается так:','https://lgz.ru/upload/opt/27-ivanov-obl.jpeg','2026-09-28T09:38:38+04:00','ready','2026-09-28T07:32:15.768985+00:00',NULL,NULL,0);
INSERT INTO "queue" VALUES(36,'https://godliteratury.ru/articles/2026/09/27/mihail-shvydkoj-stal-laureatom-ermitazhnoj-premii','Год литературы','Михаил Швыдкой стал лауреатом Эрмитажной премии','В последний день Форума объединенных культур по традиции вручили Эрмитажную премию. Георгиевский зал Зимнего дворца был полон гостей: вице-премьер Татьяна Голикова, министр культуры РФ Ольга Любимова, губернатор Санкт-Петербурга Александр Беглов, директор Эрмитажа Михаил Пиотровский.
INSERT INTO "queue" VALUES(37,'https://gorky.media/fragments/nenavidet-ameriku-pravilno','Горький','Ненавидеть Америку правильно','В антиамериканских литературных произведениях — советских и зарубежных, старых и новых — нехватки не было. Множество советских довоенных произведений как нельзя лучше подходили для антиамериканской кампании конца 1940-х годов. Поэтому в литературе, в отличие от киноиндустрии, не было необходимости диктовать темы и заказывать новые произведения. В 1949 году Агитпроп предписал эстрадным коллективам и цирковым труппам включить в репертуар «мастеров художественного чтения», а также дал указание самодеятельным театрам сосредоточиться на литературных и музыкальных постановках с антиамериканской…','https://cdn.gorky.media/storage/files/eb99e73b0d1c8ce2eda6cd877e130983_large.jpg',NULL,'ready','2026-09-28T08:32:08.844693+00:00',NULL,NULL,0);
